    for (ip in ipAddressRange) {
        if ((isInRange && ip === targetIP) || (!isInRange)) {
            anomalies.push("Port " + port + ": IP address " + ip + " is open");
            break; // Exit the loop after finding a match
        }
    }
}

// Display the anomalies found in the network scan results
anomalies.forEach(function(anomaly) {
    alert(anomaly);
